def second_largest(nums):
    max_num, second_max_num = float('-inf'), float('-inf')
    for num in nums:
        if num > max_num:
            second_max_num, max_num = max_num, num
        elif num > second_max_num and num != max_num:
            second_max_num = num
    return second_max_num

def count_unique_pairs(lst):
    pairs = set()
    for pair in lst:
        pair_str = str(pair)
        pairs.add(pair_str)
    return len(pairs)

def count_more_than_n(lst, n):
    count = {} 
    for i in lst:
        if i in count:
            count[i] += 1
        else:
            count[i] = 1
    res = []
    for k, v in count.items():
        if v > n:
            res.append(k)
    return len(res)

