def second_largest(nums):
    if len(nums) < 2:
        return None
    max_num = max(nums)
    max_index = nums.index(max_num)
    nums[max_index] = -1
    second_max = None
    for i in range(len(nums)):
        if nums[i] != -1 and (second_max is None or nums[i] > second_max):
            second_max = nums[i]
    return second_max

