Here is a Python solution using the BFS algorithm. The solution uses the built-in collections.deque and collections.defaultdict data structures.

import collections

def bfs(graph, start, end):
    queue = collections.deque([(start, [start])])
    visited = set()
    while queue:
        node, path = queue.popleft()
        if node == end:
            return path
        visited.add(node)
        for neighbor, weight in graph[node]:
            if neighbor not in visited:
                queue.append((neighbor, path + [neighbor]))
    return None

    def print_shortest_path(graph, start, end):
        path = bfs(graph, start, end)
        if path is None:
            print('No path found')
        else:
            print('Shortest path:', path)

    graph = {
        0: [(1, 4), (2, 2)],
        1: [(0, 4), (2, 1), (3, 5)],
        2: [(0, 2), (1, 1), (3, 1), (4, 3)],
        3: [(1, 5), (2, 1), (4, 1)],
        4: [(0, 4), (2, 3), (3, 1)]
    }
    print_shortest_path(graph, 1, 4)

def lcs(s1, s2):
    m = len(s1)
    n = len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    longest = ''
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > len(longest):
                    longest = s1[i - dp[i][j]:i]
    return longest

def binary_search(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

    arr = [1, 3, 5, 7, 9]
