def read_data():
    data = list(map(list, list(input().strip().split(']['))))
    graph = [[] for _ in range(len(data))]
    for i, nodes in enumerate(data):
        for node in nodes[1:-1]:
            graph[i].append((node, data[node][i]))
    return graph

def dfs(node, parent, dist, path):
    if not graph[node]:
        return dist
    max_dist = dist
    for neighbor, weight in graph[node]:
        if neighbor != parent:
            new_dist = dfs(neighbor, node, dist + weight, path + [node])
            if new_dist > max_dist:
                max_dist = new_dist
    return max_dist

def solve():
    graph = read_data()
    max_dist = 0
    for node in range(len(graph)):
        max_dist = max(max_dist, dfs(node, -1, 0, [node]))
    return max_dist

graph = solve()
print(graph)

