def first_non_repeating(s):
    last_occurrence = {} 
    for i, char in enumerate(s):
        if char in last_occurrence:
            last_occurrence[char] = i
        else:
            last_occurrence[char] = -1
    for i, char in enumerate(s):
        if last_occurrence[char] == -1 or i != last_occurrence[char]:
            return char

