def kth_smallest(arr, k):
    if len(arr) < k:
        return None
    slow, fast = 0, k - 1
    while True:
        if arr[slow] < arr[fast]:
            if fast == len(arr) - 1:
                return arr[slow]
            fast += 1
        else:
            arr[slow], arr[fast] = arr[fast], arr[slow]
            slow += 1
            if fast == len(arr) - 1:
                fast = 0

