from collections import defaultdict

def dfs(graph, source, target):
    visited = set()
    def dfs_helper(node):
        if node == target:
            return True
        if node in visited:
            return False
        visited.add(node)
        for neighbor in graph[node]:
            if dfs_helper(neighbor):
                return True
        visited.remove(node)
        return False
    return dfs_helper(source)

# Example usage:
graph = defaultdict(list)
# ... (fill the graph with edges)
print(dfs(graph, 'A', 'F'))```

