def count_elements(lst):
    counter = {} 
    for element in lst:
        if element in counter:
            counter[element] += 1
        else:
            counter[element] = 1
    return counter

def count_multiples(lst, n):
    counter = count_elements(lst)
    return sum(1 for element, count in counter.items() if count > n)

def main():
    lst = [1, 2, 2, 3, 3, 3, 4, 4, 4, 4, 5]
    print(count_multiples(lst))

if __name__ == '__main__':
    main()```

