def max_diff_bubble_sort(numbers):
    n = len(numbers)
    max_diff = 0
    for i in range(n):
        for j in range(n-i-1):
            if numbers[j] > numbers[j+1] and numbers[j+1] - numbers[j] > max_diff:
                numbers[j], numbers[j+1] = numbers[j+1], numbers[j]
                max_diff = numbers[j+1] - numbers[j]
    return numbers
