def count_repeated_elements(lst, n):
	lst.sort()
	count = 0
	prev = lst[0]
	for i in range(1, len(lst)):
		if lst[i] == prev and lst.count(lst[i]) > n:
			count += 1
		prev = lst[i]
	return count

def count_target(lst, target):
    count = 0
    for num in lst:
        if num == target:
            count += 1
    return count

