class ListNode: 
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def middle_node(head: ListNode) -> ListNode:
    mid = slow = fast = head
    while fast and fast.next: 
        slow = slow.next
        fast = fast.next.next
    return slow
```

def find_first_occurrence(arr, target):
    n = len(arr)
    if n == 0:
        return -1
    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            if mid == 0 or arr[mid - 1] != target:
                return mid
            right = mid - 1
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1
